func accept_input(peer: int, command: Dictionary) -> bool:
	if not members.has(peer): return false
	var room: Dictionary = rooms[members[peer]]
	var who: int = room.peers.find(peer)
	if room.phase != "running" or room.game == null or who < 0: return false
	if command.size() != 3 or typeof(command.get("direction")) != TYPE_VECTOR2 or typeof(command.get("sequence")) != TYPE_INT or typeof(command.get("match_id")) != TYPE_STRING: return false
	if command.match_id != room.match_id: return false
	return room.game.set_input(who, command.direction, command.sequence)
func step() -> void:
	for room: Dictionary in rooms.values():
		if room.phase == "lobby":
			var closed: Array = room.staging_map.DOORS.keys()
			for peer in room.peers:
				var intention: Dictionary = room.lobby_inputs[peer]
				var direction: Vector2 = intention.direction if room.lobby_tick - intention.tick < Rules.INPUT_TIMEOUT_TICKS else Vector2.ZERO
				room.positions[peer] = room.staging_map.move(room.positions[peer], direction, Rules.STEP, closed)
				intention.ack = intention.sequence
			room.lobby_tick += 1
			if room.lobby_tick % 2 == 0: lobby(room)
			continue
		if room.phase != "running": continue
		room.game.step()
		if room.game.finished:
			room.phase = "finished"
			views(room)
		elif room.game.tick % 2 == 0: views(room)

static func project(game, who: int, token: String = "fixture", phase: String = "running") -> Dictionary:
	if phase == "running" and game.finished: phase = "finished"
	var visible: Array = []
	var observer: Dictionary = game.explorers[who]
	var map = game.Map
	var closed: Array[String] = map.closed_door_ids(game.doors)
	var radius: float = map.vision_radius(observer.position, observer.has_light, closed)
	for i in range(game.explorers.size()):
		var p: Dictionary = game.explorers[i]
		if i == who or (p.state != "escaped" and map.can_see_with_radius(observer.position, p.position, radius, closed, observer.has_light)):
			var actor := {"name": p.name, "position": p.position, "velocity": p.velocity, "region": p.region, "state": p.state, "has_light": p.has_light, "has_relic": p.has_relic}
			if i == who:
				actor["breath"] = p.breath
				actor["score"] = p.score
				actor["region_depth"] = game.water_depths[p.region]
				if game.expedition != null:
					for field in ["health", "breath_max", "gear", "tank", "ammo", "treasure", "facing", "last_loot", "loot_serial"]: actor[field] = p[field].duplicate(true) if p[field] is Dictionary else p[field]
					actor["move_factor"] = game.expedition.movement_factor(game, who)
					actor["oxygen_enabled"] = game.expedition.has_oxygen(game, who)
			if game.expedition != null:
				actor["stunned"] = p.stun_until > game.tick
				actor["hurt"] = p.hurt_until > game.tick
			visible.append(actor)
		else:
			visible.append({"name": p.name, "state": "hidden"})

def submit(kind: str, endpoint: str, payload: dict) -> None:
    path = receipt(kind)
    if path.exists():
        previous = json.loads(path.read_text())
        # A documented HTTP 429 rejected the request before it was accepted.
        # Ambiguous submissions and accepted jobs must never be retried.
        if previous.get('state') != 'rate_limited' or previous.get('payload') != payload:
            raise PipelineError(f'{kind} already has a receipt. Use status/collect; no duplicate POST.')
    data = {'name': NAME, 'kind': kind, 'endpoint': endpoint, 'payload': payload, 'state': 'submitting'}
    write_json(path, data)
    try:
        data['response'] = request('POST', endpoint, payload)
    except PipelineError as error:
        if str(error).startswith('PixelLab HTTP 429.'):
            data.update(state='rate_limited', rejected_status=429)
            write_json(path, data)
        raise
    data['state'] = 'processing'
    write_json(path, data)
    response = data['response']
    print(json.dumps({'stage': kind, 'status': response.get('status'),
                      'job_count': len(response.get('background_job_ids', [])) or 1,
                      'usage': response.get('usage')}, indent=2))

void fragment() {
	float relief = texture(depth_map, UV).r;
	if (!near_is_white) { relief = 1.0 - relief; }
	vec2 sample_uv = UV + offset_pixels * TEXTURE_PIXEL_SIZE * (relief - focus_depth);
	sample_uv = clamp(sample_uv, TEXTURE_PIXEL_SIZE * 0.5, vec2(1.0) - TEXTURE_PIXEL_SIZE * 0.5);
	// Keep vertex tint and CanvasItem lighting; do not multiply two texture samples.
	vec4 painted = texture(TEXTURE, sample_uv);
	if (soft_focus > 0.0) {
		vec2 blur = TEXTURE_PIXEL_SIZE * soft_focus;
		painted = painted * 0.4
			+ texture(TEXTURE, sample_uv + vec2(blur.x, 0.0)) * 0.15
			+ texture(TEXTURE, sample_uv - vec2(blur.x, 0.0)) * 0.15
			+ texture(TEXTURE, sample_uv + vec2(0.0, blur.y)) * 0.15
			+ texture(TEXTURE, sample_uv - vec2(0.0, blur.y)) * 0.15;
	}
	float value = dot(painted.rgb, vec3(0.2126, 0.7152, 0.0722));
	painted.rgb = mix(painted.rgb, vec3(value), desaturation);
	COLOR = painted * vertex_modulate;
}
